const base='http://127.0.0.1:8000/';
const routes=['index.html','corporate.html','energy.html','products.html','product.html','urea-46.html','caustic-soda-solid.html','sodium-sulphate-anhydrous.html','sales.html','technology.html','evidence-axis.html','ventures.html','contact.html','privacy.html','legal.html','404.html'];
const policyViewports=[[1920,1080],[1440,900],[768,1024],[390,844],[360,800]];
const smokeViewports=[[1440,900],[390,844]];
const tracker=/google-analytics|googletagmanager|doubleclick|facebook\.com\/tr|connect\.facebook|clarity\.ms|hotjar|segment\.com|mixpanel|plausible|umami/i;
const report={policyCases:[],mobileCases:[],dataFlowCases:[],linkQA:[],rfq:null,crawl:{records:[],failures:[]},smoke:[],failures:[],summary:{}};
const fail=(scope,msg,data={})=>report.failures.push({scope,msg,...data});
const ok=(c,s,m,d={})=>{if(!c)fail(s,m,d)};
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function newPage(browser,w=1440,h=900){const ctx=await browser.createBrowserContext();const page=await ctx.newPage();await page.setViewport({width:w,height:h,deviceScaleFactor:1});const e={console:[],page:[],failed:[],requests:[]};page.on('console',m=>{if(m.type()==='error')e.console.push(m.text())});page.on('pageerror',x=>e.page.push(String(x)));page.on('requestfailed',r=>e.failed.push({url:r.url(),error:r.failure()?.errorText||''}));page.on('request',r=>e.requests.push({url:r.url(),type:r.resourceType(),method:r.method()}));return{ctx,page,e}}
async function go(page,route){const u=route.startsWith('http')?route:base+route;const r=await page.goto(u,{waitUntil:'domcontentloaded',timeout:30000});await sleep(650);return{status:r?.status()||0,url:page.url()}}
function classify(u){try{const x=new URL(u);return{x,external:x.origin!==new URL(base).origin}}catch{return{x:null,external:false}}}
async function shell(page,scope,w){const d=await page.evaluate(()=>{const ids=[...document.querySelectorAll('[id]')].map(x=>x.id);return{sw:document.documentElement.scrollWidth,cw:document.documentElement.clientWidth,h1:document.querySelectorAll('main h1').length,dup:[...new Set(ids.filter((x,i)=>ids.indexOf(x)!==i))],main:!!document.querySelector('main'),header:!!document.querySelector('.site-header'),footer:!!document.querySelector('.site-footer')}});ok(d.main&&d.header&&d.footer,scope,'site shell missing',d);ok(d.h1===1,scope,'expected exactly one main H1',d);ok(d.sw<=w+1,scope,'horizontal overflow',d);ok(!d.dup.length,scope,'duplicate IDs',d);return d}
async function policyMetrics(page){return page.evaluate(()=>{const rect=e=>{if(!e)return null;const r=e.getBoundingClientRect();return{x:r.x,right:r.right,width:r.width,height:r.height,bottom:r.bottom}};const ps=[...document.querySelectorAll('main p')].map(p=>({text:p.textContent.trim().slice(0,90),size:parseFloat(getComputedStyle(p).fontSize),line:parseFloat(getComputedStyle(p).lineHeight)||0,width:p.getBoundingClientRect().width}));const emails=[...document.querySelectorAll('main a[href^="mailto:"]')].map(a=>({text:a.textContent.trim(),...rect(a)}));const phones=[...document.querySelectorAll('main a[href^="tel:"]')].map(a=>({text:a.textContent.trim(),...rect(a)}));const actions=[...document.querySelectorAll('main .button-link,main .legal-link-row a')].map(a=>({text:a.textContent.trim(),...rect(a)}));const sectionCaps=[...document.querySelectorAll('main .section-cap')].map(rect);const company=[...document.querySelectorAll('main strong')].find(e=>e.textContent.includes('UNIQE OTOMOTİV'))||null;const address=document.querySelector('main address');return{ps,emails,phones,actions,sectionCaps,company:rect(company),address:rect(address),bodySize:parseFloat(getComputedStyle(document.body).fontSize),lastUpdated:[...document.querySelectorAll('main')][0]?.innerText.includes('1 September 2026')||false,heroBefore:getComputedStyle(document.querySelector('.legal-hero'),'::before').backgroundImage}})}
(async()=>{const browser=await puppeteer.launch({executablePath:process.env.CHROME,headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});try{
// 1) Primary five-viewport visual/readability QA: privacy + legal = 10 cases.
for(const route of ['privacy.html','legal.html'])for(const [w,h] of policyViewports){const scope=`${route}-${w}x${h}`;const{ctx,page,e}=await newPage(browser,w,h);const nav=await go(page,route);ok([200,304].includes(nav.status),scope,'policy route status',{nav});await shell(page,scope,w);const m=await policyMetrics(page);ok(m.lastUpdated,scope,'last-updated date missing');ok(!/url\(/i.test(m.heroBefore),scope,'remote/inherited hero image still rendered',{heroBefore:m.heroBefore});for(const p of m.ps)if(p.text)ok(p.size>=15,scope,'legal body text below 15px',{p});for(const c of m.sectionCaps)ok(c.width<=Math.min(w,1000)+2,scope,'legal line-length container too wide',{c});for(const a of [...m.emails,...m.phones])ok(a.x>=-1&&a.right<=w+1,scope,'contact text clipped',{a});if(m.company)ok(m.company.x>=-1&&m.company.right<=w+1,scope,'company name clipped',{company:m.company});if(m.address)ok(m.address.x>=-1&&m.address.right<=w+1,scope,'address clipped',{address:m.address});if(w<=390){for(const a of m.actions)ok(a.x>=-1&&a.right<=w+1&&a.height>=40,scope,'mobile primary action clipped/not touch-safe',{a});report.mobileCases.push({route,w,h,minParagraphFont:Math.min(...m.ps.filter(p=>p.text).map(p=>p.size)),emails:m.emails,phones:m.phones,actions:m.actions})}ok(e.console.length===0&&e.page.length===0&&e.failed.length===0,scope,'policy browser errors',{e});await page.screenshot({path:path.join(OUT,`screenshots/${route.replace('.html','')}/${route.replace('.html','')}-${w}x${h}.png`),fullPage:true});report.policyCases.push({route,w,h,status:nav.status,bodyParagraphMin:Math.min(...m.ps.filter(p=>p.text).map(p=>p.size)),browserErrors:{console:e.console.length,page:e.page.length,failed:e.failed.length}});await ctx.close()}
// 2) 16 routes x two viewports: privacy instrumentation + sitewide smoke in clean contexts.
for(const route of routes)for(const [w,h] of smokeViewports){const scope=`flow-smoke-${route}-${w}`;const{ctx,page,e}=await newPage(browser,w,h);await page.evaluateOnNewDocument(()=>{window.__p17={fetch:[],beacon:[]};const f=window.fetch;window.fetch=function(...a){try{window.__p17.fetch.push(String(a[0]))}catch{}return f.apply(this,a)};const b=navigator.sendBeacon?.bind(navigator);if(b)navigator.sendBeacon=function(u,d){try{window.__p17.beacon.push(String(u))}catch{}return b(u,d)}});const cdp=await page.createCDPSession();await cdp.send('Network.enable');const before=(await cdp.send('Network.getAllCookies')).cookies||[];let nav={status:0};try{nav=await go(page,route)}catch(err){fail(scope,'navigation error',{error:String(err)})}await shell(page,scope,w);const after=(await cdp.send('Network.getAllCookies')).cookies||[];const obs=await page.evaluate(async()=>{const idb=typeof indexedDB?.databases==='function'?await indexedDB.databases().catch(()=>[]):[];const sw='serviceWorker'in navigator?await navigator.serviceWorker.getRegistrations().then(x=>x.map(r=>({scope:r.scope,script:r.active?.scriptURL||null}))).catch(()=>[]):[];const cs=('cookieStore'in window&&cookieStore.getAll)?await cookieStore.getAll().catch(()=>[]):'unsupported';return{documentCookie:document.cookie,cookieStore:cs,localStorage:Object.keys(localStorage),sessionStorage:Object.keys(sessionStorage),indexedDB:idb.map(x=>({name:x.name||null,version:x.version||null})),serviceWorkers:sw,iframes:[...document.querySelectorAll('iframe')].map(x=>x.src).filter(Boolean),forms:[...document.forms].map(f=>({id:f.id||null,action:f.getAttribute('action')||'',method:(f.getAttribute('method')||'get').toLowerCase()})),hooks:window.__p17||{fetch:[],beacon:[]}}});const ext=e.requests.map(r=>({...r,...classify(r.url)})).filter(x=>x.external).map(x=>({url:x.url,host:x.x.hostname,type:x.type,method:x.method}));const analytics=e.requests.filter(r=>tracker.test(r.url));const xhr=e.requests.filter(r=>['xhr','fetch'].includes(r.type));ok([200,304].includes(nav.status),scope,'smoke status',{nav});ok(after.length===0&&obs.documentCookie==='',scope,'cookie observed',{after,documentCookie:obs.documentCookie});ok(obs.localStorage.length===0&&obs.sessionStorage.length===0&&obs.indexedDB.length===0&&obs.serviceWorkers.length===0,scope,'browser storage/SW observed',{obs});ok(analytics.length===0,scope,'analytics/advertising request observed',{analytics});ok(xhr.length===0&&obs.hooks.fetch.length===0&&obs.hooks.beacon.length===0,scope,'XHR/fetch/beacon observed',{xhr,hooks:obs.hooks});ok(obs.iframes.length===0,scope,'third-party iframe/embed observed',{iframes:obs.iframes});const badHosts=ext.filter(x=>x.host!=='images.unsplash.com');ok(badHosts.length===0,scope,'unexpected third-party host',{badHosts});const badTypes=ext.filter(x=>x.type!=='image');ok(badTypes.length===0,scope,'unexpected non-image third-party resource',{badTypes});ok(e.console.length===0&&e.page.length===0&&e.failed.length===0,scope,'sitewide browser errors',{e});report.dataFlowCases.push({route,w,h,cookies:after.length,localStorage:obs.localStorage,sessionStorage:obs.sessionStorage,indexedDB:obs.indexedDB,serviceWorkers:obs.serviceWorkers,thirdParty:ext,analyticsAdvertising:analytics.length,xhrFetchBeacon:xhr.length+obs.hooks.fetch.length+obs.hooks.beacon.length,forms:obs.forms});report.smoke.push({route,w,h,status:nav.status,pass:!report.failures.some(f=>f.scope===scope)});await ctx.close()}
const imageRoutes=[...new Set(report.dataFlowCases.filter(c=>c.thirdParty.some(x=>x.type==='image')).map(c=>c.route))].sort();ok(JSON.stringify(imageRoutes)===JSON.stringify(['energy.html','index.html','products.html','sales.html']),'data-flow','external-image route set differs',{imageRoutes});
// 3) Link QA.
for(const route of ['privacy.html','legal.html']){const{ctx,page}=await newPage(browser,1440,900);await go(page,route);const links=await page.evaluate(()=>[...document.querySelectorAll('a[href]')].map(a=>({text:a.textContent.trim().replace(/\s+/g,' '),href:a.getAttribute('href')})));const req=route==='privacy.html'?['legal.html','contact.html']:['privacy.html','sales.html','contact.html'];for(const href of req){const pass=links.some(a=>a.href===href);report.linkQA.push({source:route,target:href,pass});ok(pass,'link-qa',`${route} missing ${href}`)}await ctx.close()}
// Footer links to both legal routes on every public route.
for(const route of routes){const{ctx,page}=await newPage(browser,1200,800);await go(page,route);const f=await page.evaluate(()=>[...document.querySelectorAll('.global-footer-nav a')].map(a=>a.getAttribute('href')));for(const href of ['privacy.html','legal.html'])ok(f.includes(href),'footer-link',`${route} footer missing ${href}`);await ctx.close()}
// 4) RFQ data-flow interaction: fill fields, verify mailto update, no network submission.
{const{ctx,page,e}=await newPage(browser,390,844);await page.evaluateOnNewDocument(()=>{window.__rfqNet=[];const f=window.fetch;window.fetch=function(...a){window.__rfqNet.push(['fetch',String(a[0])]);return f.apply(this,a)};const b=navigator.sendBeacon?.bind(navigator);if(b)navigator.sendBeacon=function(u,d){window.__rfqNet.push(['beacon',String(u)]);return b(u,d)}});await go(page,'sales.html');const before=e.requests.length;await page.type('#rfq-product','Urea 46');await page.type('#rfq-grade','Granular');await page.type('#rfq-quantity','100 MT');await page.type('#rfq-destination','Istanbul');await page.type('#rfq-contact-name','QA Contact');await page.type('#rfq-email','qa@example.com');await sleep(150);const d=await page.evaluate(()=>({href:document.querySelector('#rfq-email-action').getAttribute('href'),formAction:document.querySelector('#rfq-builder').getAttribute('action')||'',net:window.__rfqNet||[]}));const newNet=e.requests.slice(before).filter(r=>['xhr','fetch'].includes(r.type));const pass=d.href.startsWith('mailto:sales@uniqueholding.com.tr?')&&decodeURIComponent(d.href).includes('Urea 46')&&decodeURIComponent(d.href).includes('100 MT')&&d.formAction===''&&newNet.length===0&&d.net.length===0;report.rfq={...d,newNet,pass};ok(pass,'rfq','RFQ handoff behavior mismatch',report.rfq);await ctx.close()}
// 5) Internal link / fragment crawl.
const seen=new Map();for(const route of routes){const{ctx,page}=await newPage(browser,1200,800);let nav;try{nav=await go(page,route)}catch(err){report.crawl.failures.push({source:route,msg:'source navigation',error:String(err)});await ctx.close();continue}if(![200,304].includes(nav.status)){report.crawl.failures.push({source:route,msg:'source status',status:nav.status});await ctx.close();continue}const links=await page.evaluate(()=>[...document.querySelectorAll('a[href]')].map(a=>({text:a.textContent.trim().replace(/\s+/g,' '),href:a.getAttribute('href'),target:a.getAttribute('target'),rel:a.getAttribute('rel')||''})));for(const a of links){if(!a.href)continue;if(a.href.startsWith('mailto:')){if(!/^mailto:[^?\s]+@[^?\s]+(?:\?[^\s]*)?$/.test(a.href))report.crawl.failures.push({source:route,msg:'bad mailto',a});continue}if(a.href.startsWith('tel:')){if(!/^tel:\+\d{10,15}$/.test(a.href))report.crawl.failures.push({source:route,msg:'bad tel',a});continue}if(/^https?:/i.test(a.href)){if(a.target==='_blank'&&!a.rel.split(/\s+/).includes('noopener'))report.crawl.failures.push({source:route,msg:'external blank lacks noopener',a});continue}if(a.href.startsWith('#')){seen.set(route+a.href,{source:route,href:a.href,target:route,fragment:a.href.slice(1)});continue}const u=new URL(a.href,base+route);if(u.origin===new URL(base).origin){seen.set(route+'->'+a.href,{source:route,href:a.href,target:u.pathname.replace(/^\//,'')||'index.html',fragment:u.hash.slice(1)})}}await ctx.close()}
for(const rec of seen.values()){const{ctx,page}=await newPage(browser,1000,700);let status=0,fragmentOk=true;try{const g=await go(page,rec.target+(rec.fragment?'#'+rec.fragment:''));status=g.status;if(rec.fragment)fragmentOk=await page.evaluate(id=>!!document.getElementById(id),rec.fragment)}catch(err){fragmentOk=false}const pass=[200,304].includes(status)&&fragmentOk;report.crawl.records.push({...rec,status,fragmentOk,pass});if(!pass)report.crawl.failures.push({...rec,status,fragmentOk,msg:'internal target/fragment failed'});await ctx.close()}ok(report.crawl.failures.length===0,'crawl','internal-link/fragment crawl failures',{failures:report.crawl.failures});
}finally{await browser.close()}
report.summary={policyCases:report.policyCases.length,mobileCases:report.mobileCases.length,dataFlowCases:report.dataFlowCases.length,smokeCases:report.smoke.length,smokeFailures:report.smoke.filter(x=>!x.pass).length,linkCases:report.linkQA.length,rfqPass:!!report.rfq?.pass,crawlRecords:report.crawl.records.length,crawlFailures:report.crawl.failures.length,failures:report.failures.length};fs.writeFileSync(path.join(OUT,'reports/phase17-browser-report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify(report.summary,null,2));if(report.failures.length)process.exit(1)})();